1	import { useCallback, useEffect, useRef, useState } from 'react';
2	
3	import { cn } from '@app/lib/utils';
4	import { Pause, Play, Volume2 } from 'lucide-react';
5	import { AudioWaveform } from './AudioWaveform';
6	
7	interface AudioPreviewButtonProps {
8	  /** Full URL to the audio file */
9	  audioUrl: string;
10	  /** Unique hash for waveform generation */
11	  hash: string;
12	  /** Preview duration in milliseconds */
13	  previewDuration?: number;
14	  /** Additional CSS classes */
15	  className?: string;
16	}
17	
18	/**
19	 * Audio preview component with play button overlay.
20	 * Features:
21	 * - Plays audio preview on click (not hover, to avoid being jarring)
22	 * - Shows animated waveform while playing
23	 * - Auto-stops after preview duration
24	 * - Fades out at the end
25	 */
26	export function AudioPreviewButton({
27	  audioUrl,
28	  hash,
29	  previewDuration = 5000,
30	  className,
31	}: AudioPreviewButtonProps) {
32	  const audioRef = useRef<HTMLAudioElement>(null);
33	  const fadeIntervalRef = useRef<number | undefined>(undefined);
34	  const fadeTimeoutRef = useRef<number | undefined>(undefined);
35	  const [isPlaying, setIsPlaying] = useState(false);
36	  const [isHovering, setIsHovering] = useState(false);
37	
38	  // Clean up on unmount
39	  useEffect(() => {
40	    return () => {
41	      if (fadeTimeoutRef.current !== undefined) {
42	        clearTimeout(fadeTimeoutRef.current);
43	      }
44	      if (fadeIntervalRef.current !== undefined) {
45	        clearInterval(fadeIntervalRef.current);
46	      }
47	      if (audioRef.current) {
48	        audioRef.current.pause();
49	        audioRef.current.src = '';
50	      }
51	    };
52	  }, []);
53	
54	  const fadeOutAndStop = useCallback(() => {
55	    const audio = audioRef.current;
56	    if (!audio) {
57	      return;
58	    }
59	
60	    // Fade out over 500ms
61	    const startVolume = audio.volume;
62	    const fadeSteps = 10;
63	    const stepDuration = 500 / fadeSteps;
64	    let currentStep = 0;
65	
66	    fadeIntervalRef.current = window.setInterval(() => {
67	      currentStep++;
68	      audio.volume = Math.max(0, startVolume * (1 - currentStep / fadeSteps));
69	
70	      if (currentStep >= fadeSteps) {
71	        if (fadeIntervalRef.current !== undefined) {
72	          clearInterval(fadeIntervalRef.current);
73	          fadeIntervalRef.current = undefined;
74	        }
75	        audio.pause();
76	        audio.currentTime = 0;
77	        audio.volume = startVolume;
78	        setIsPlaying(false);
79	      }
80	    }, stepDuration);
81	  }, []);
82	
83	  const togglePlay = useCallback(
84	    (e: React.MouseEvent) => {
85	      e.stopPropagation();
86	
87	      const audio = audioRef.current;
88	      if (!audio) {
89	        return;
90	      }
91	
92	      if (isPlaying) {
93	        // Stop immediately — clear any pending fade timeout
94	        if (fadeTimeoutRef.current !== undefined) {
95	          clearTimeout(fadeTimeoutRef.current);
96	          fadeTimeoutRef.current = undefined;
97	        }
98	        if (fadeIntervalRef.current !== undefined) {
99	          clearInterval(fadeIntervalRef.current);
100	          fadeIntervalRef.current = undefined;
101	        }
102	        audio.pause();
103	        audio.currentTime = 0;
104	        setIsPlaying(false);
105	      } else {
106	        // Start playing
107	        audio.currentTime = 0;
108	        audio.volume = 0.7; // Start at 70% volume
109	        audio.play().catch(() => {
110	          // Autoplay may be blocked
111	        });
112	        setIsPlaying(true);
113	
114	        // Schedule fade out — track timeout for cleanup.
115	        // Guard against very short previewDuration values (≤500ms).
116	        const fadeDelay =
117	          previewDuration > 500 ? previewDuration - 500 : Math.max(previewDuration - 50, 0);
118	        fadeTimeoutRef.current = window.setTimeout(() => {
119	          fadeTimeoutRef.current = undefined;
120	          fadeOutAndStop();
121	        }, fadeDelay);
122	      }
123	    },
124	    [isPlaying, previewDuration, fadeOutAndStop],
125	  );
126	
127	  const handleAudioEnded = useCallback(() => {
128	    setIsPlaying(false);
129	  }, []);
130	
131	  return (
132	    <div
133	      className={cn(
134	        'relative h-full w-full flex items-center justify-center',
135	        'bg-gradient-to-br from-purple-50 to-pink-50 dark:from-purple-950/30 dark:to-pink-950/30',
136	        className,
137	      )}
138	      onMouseEnter={() => setIsHovering(true)}
139	      onMouseLeave={() => setIsHovering(false)}
140	    >
141	      {/* Hidden audio element */}
142	      <audio ref={audioRef} src={audioUrl} preload="none" onEnded={handleAudioEnded} />
143	
144	      {/* Waveform visualization */}
145	      <AudioWaveform
146	        hash={hash}
147	        isPlaying={isPlaying}
148	        barCount={7}
149	        barWidth={4}
150	        minBarHeight={8}
151	        maxBarHeight={24}
152	        showIcon
153	        iconSize="h-10 w-10"
154	      />
155	
156	      {/* Play/Pause button overlay */}
157	      <button
158	        onClick={togglePlay}
159	        className={cn(
160	          'absolute inset-0 flex items-center justify-center',
161	          'transition-opacity duration-200',
162	          isHovering || isPlaying ? 'opacity-100' : 'opacity-0',
163	        )}
164	        aria-label={isPlaying ? 'Pause audio preview' : 'Play audio preview'}
165	      >
166	        <div
167	          className={cn(
168	            'rounded-full bg-purple-600/80 dark:bg-purple-500/80 p-3 backdrop-blur-sm',
169	            'transition-all duration-200',
170	            'hover:bg-purple-600 dark:hover:bg-purple-500 hover:scale-110',
171	            'shadow-lg',
172	          )}
173	        >
174	          {isPlaying ? (
175	            <Pause className="h-5 w-5 text-white" fill="currentColor" />
176	          ) : (
177	            <Play className="h-5 w-5 text-white ml-0.5" fill="currentColor" />
178	          )}
179	        </div>
180	      </button>
181	
182	      {/* Playing indicator */}
183	      {isPlaying && (
184	        <div className="absolute bottom-2 left-2 flex items-center gap-1.5 px-2 py-1 bg-purple-600/80 rounded text-white text-xs">
185	          <Volume2 className="h-3 w-3" />
186	          <span>Preview</span>
187	        </div>
188	      )}
189	
190	      {/* Hover hint */}
191	      {isHovering && !isPlaying && (
192	        <div className="absolute bottom-2 left-1/2 -translate-x-1/2 px-2 py-1 bg-black/60 rounded text-white text-xs whitespace-nowrap">
193	          Click to preview
194	        </div>
195	      )}
196	    </div>
197	  );
198	}
