17	  onClick: () => void;
18	  tabIndex?: number;
19	  onFocus?: () => void;
20	  isSelectionMode?: boolean;
21	  isSelected?: boolean;
22	  onToggleSelection?: (hash: string) => void;
23	  isFocused?: boolean;
24	  /** Whether this item is currently being viewed in the modal */
25	  isViewing?: boolean;
26	}
27	
28	export function MediaCard({
29	  item,
30	  onClick,
31	  tabIndex = 0,
32	  onFocus,
33	  isSelectionMode = false,
34	  isSelected = false,
35	  onToggleSelection,
36	  isFocused = false,
37	  isViewing = false,
38	}: MediaCardProps) {
39	  const [imageLoaded, setImageLoaded] = useState(false);
40	  const [imageError, setImageError] = useState(false);
41	  const [isVisible, setIsVisible] = useState(false);
42	  const cardRef = useRef<HTMLDivElement>(null);
43	
44	  // Build the full media URL including API base for dev mode
45	  const mediaUrl = useMemo(() => {
46	    const baseUrl = getApiBaseUrl();
47	    return `${baseUrl}${item.url}`;
48	  }, [item.url]);
49	
50	  // Use IntersectionObserver to detect when card is visible
51	  useEffect(() => {
52	    const card = cardRef.current;
53	    if (!card) {
54	      return;
55	    }
56	
57	    const observer = new IntersectionObserver(
58	      (entries) => {
59	        const [entry] = entries;
60	        if (entry.isIntersecting) {
61	          setIsVisible(true);
62	          // Once visible, no need to observe anymore
63	          observer.disconnect();
64	        }
65	      },
66	      {
67	        root: null,
68	        rootMargin: '100px', // Start loading slightly before visible
69	        threshold: 0,
70	      },
71	    );
72	
73	    observer.observe(card);
74	
75	    return () => {
76	      observer.disconnect();
77	    };
78	  }, []);
79	
80	  const KindIcon = getKindIcon(item.kind);
81	  const isPlayable = item.kind === 'video' || item.kind === 'audio';
82	  const isDownloadOnly = item.kind === 'other';
83	
84	  const handlePrimaryAction = () => {
85	    if (isSelectionMode && onToggleSelection) {
86	      onToggleSelection(item.hash);
87	      return;
88	    }
89	    if (isDownloadOnly) {
90	      downloadMediaItem(mediaUrl, item.hash, item.mimeType);
91	    } else {
92	      onClick();
93	    }
94	  };
95	
96	  const handleCheckboxClick = (e: React.MouseEvent) => {
97	    e.stopPropagation();
98	    onToggleSelection?.(item.hash);
99	  };
100	
101	  const handleDownloadClick = (e: React.MouseEvent) => {
102	    e.stopPropagation();
103	    downloadMediaItem(mediaUrl, item.hash, item.mimeType);
104	  };
105	
106	  return (
107	    <div
108	      ref={cardRef}
109	      className={cn(
110	        'group relative rounded-xl border bg-card',
111	        'transition-all duration-200',
112	        'hover:border-primary/50 hover:shadow-md',
113	        isViewing
114	          ? 'border-primary ring-2 ring-primary/40 shadow-lg'
115	          : isSelected
116	            ? 'border-primary ring-2 ring-primary/20'
117	            : isFocused
118	              ? 'border-primary/70 ring-2 ring-primary/30 ring-offset-2 ring-offset-background'
119	              : 'border-border',
120	      )}
121	    >
122	      {/* Primary action overlay — covers the entire card so the card itself
123	          is not an interactive element. Nested buttons sit above at z-10. */}
124	      <button
125	        data-media-card
126	        type="button"
127	        className="absolute inset-0 z-0 cursor-pointer rounded-xl bg-transparent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
128	        onClick={handlePrimaryAction}
129	        onFocus={onFocus}
130	        tabIndex={tabIndex}
131	        aria-label={`${getKindLabel(item.kind)}: ${item.context.evalDescription || 'Media item'}${isViewing ? ' (currently viewing)' : ''}${isSelectionMode ? (isSelected ? ' (selected)' : ' (not selected)') : ''}`}
132	      />
133	
134	      {/* Media Preview Area */}
135	      <div className="relative aspect-square overflow-hidden rounded-t-xl bg-muted/30">
136	        {item.kind === 'image' && !imageError ? (
137	          <>
138	            {!imageLoaded && <Skeleton className="absolute inset-0 rounded-none" />}
139	            <img
140	              src={mediaUrl}
141	              alt={item.context.evalDescription || 'Generated image'}
142	              className={cn(
143	                'h-full w-full object-cover transition-opacity duration-200',
144	                imageLoaded ? 'opacity-100' : 'opacity-0',
145	              )}
146	              loading="lazy"
147	              onLoad={() => setImageLoaded(true)}
148	              onError={() => setImageError(true)}
149	            />
150	          </>
151	        ) : item.kind === 'video' ? (
152	          <VideoHoverPreview videoUrl={mediaUrl} hash={item.hash} isVisible={isVisible} />
153	        ) : item.kind === 'audio' ? (
154	          <AudioPreviewButton audioUrl={mediaUrl} hash={item.hash} />
155	        ) : (
156	          <div className="flex h-full flex-col items-center justify-center gap-2 bg-gradient-to-br from-gray-50 to-slate-50 dark:from-gray-950/30 dark:to-slate-950/30">
157	            <KindIcon className="h-10 w-10 text-gray-400 dark:text-gray-500" />
158	            <span className="text-xs text-muted-foreground">{formatBytes(item.sizeBytes)}</span>
159	          </div>
160	        )}
161	
162	        {/* Download Button - Bottom Left Corner (z-10 above overlay) */}
163	        {!isSelectionMode && (
164	          <Tooltip>
165	            <TooltipTrigger asChild>
166	              <button
167	                type="button"
168	                onClick={handleDownloadClick}
169	                className={cn(
170	                  'absolute bottom-2 left-2 z-10',
171	                  'rounded-md bg-black/60 p-1.5',
172	                  'opacity-0 transition-opacity duration-200 group-hover:opacity-100 focus-visible:opacity-100 [@media(hover:none)]:opacity-100',
173	                  'hover:bg-black/80',
174	                )}
175	                aria-label="Download"
176	              >
177	                <Download className="h-3.5 w-3.5 text-white" />
178	              </button>
179	            </TooltipTrigger>
180	            <TooltipContent>Download</TooltipContent>
181	          </Tooltip>
182	        )}
183	
184	        {/* Selection Checkbox (z-10 above overlay) */}
185	        {isSelectionMode && (
186	          <button
187	            type="button"
188	            onClick={handleCheckboxClick}
189	            className={cn(
190	              'absolute top-2 right-2 z-10 flex h-6 w-6 items-center justify-center rounded-md border-2 transition-all',
191	              isSelected
192	                ? 'border-primary bg-primary text-primary-foreground'
193	                : 'border-muted-foreground/50 bg-white/90 dark:bg-zinc-800/90 hover:border-primary',
194	            )}
195	            aria-label={isSelected ? 'Deselect' : 'Select'}
196	          >
197	            {isSelected && <Check className="h-4 w-4" />}
198	          </button>
199	        )}
200	
201	        {/* Play indicator for video/audio */}
202	        {isPlayable && (
