8	interface VideoHoverPreviewProps {
9	  /** Full URL to the video file */
10	  videoUrl: string;
11	  /** Unique hash for caching thumbnails */
12	  hash: string;
13	  /** Whether the card is visible (for lazy loading) */
14	  isVisible?: boolean;
15	  /** Additional CSS classes */
16	  className?: string;
17	}
18	
19	/**
20	 * Check if the device supports hover (not a touch-only device)
21	 */
22	function useIsTouchDevice() {
23	  const [isTouch, setIsTouch] = useState(false);
24	
25	  useEffect(() => {
26	    // Check for touch capability and no hover support
27	    const mediaQuery = window.matchMedia('(hover: none)');
28	    setIsTouch(mediaQuery.matches);
29	
30	    const handler = (e: MediaQueryListEvent) => setIsTouch(e.matches);
31	    mediaQuery.addEventListener('change', handler);
32	    return () => mediaQuery.removeEventListener('change', handler);
33	  }, []);
34	
35	  return isTouch;
36	}
