38	/**
39	 * Video preview component that shows a thumbnail and plays video on hover.
40	 * Features:
41	 * - Generates and caches video thumbnails
42	 * - Plays video on intentional hover (300ms delay) on desktop
43	 * - Tap to play/pause on touch devices
44	 * - Respects prefers-reduced-motion
45	 */
46	export function VideoHoverPreview({
47	  videoUrl,
48	  hash,
49	  isVisible = true,
50	  className,
51	}: VideoHoverPreviewProps) {
52	  const videoRef = useRef<HTMLVideoElement>(null);
53	  const [isVideoLoaded, setIsVideoLoaded] = useState(false);
54	  const [isVideoPlaying, setIsVideoPlaying] = useState(false);
55	  const [isTouchPlaying, setIsTouchPlaying] = useState(false);
56	  const isTouchDevice = useIsTouchDevice();
57	
58	  const { isIntentional, hoverProps } = useHoverIntent({
59	    delay: 300,
60	    respectReducedMotion: true,
61	  });
62	
63	  // Whether the user wants to play: intentional hover (desktop) or tap (touch)
64	  const wantsToPlay = isTouchDevice ? isTouchPlaying : isIntentional;
65	
66	  useEffect(() => {
67	    const video = videoRef.current;
68	    if (!video) {
69	      return;
70	    }
71	
72	    if (wantsToPlay) {
73	      if (isVideoLoaded) {
74	        video.currentTime = 0;
75	        video.play().catch(() => {
76	          // Autoplay may be blocked, silently fail
77	        });
78	        setIsVideoPlaying(true);
79	      } else {
80	        // With preload="none", canplay won't fire until we initiate loading.
81	        // Calling load() triggers the browser to fetch the video; once enough
82	        // data is buffered, onCanPlay fires and sets isVideoLoaded=true,
83	        // which re-triggers this effect to start playback.
84	        video.load();
85	      }
86	    } else {
87	      video.pause();
88	      video.currentTime = 0;
89	      setIsVideoPlaying(false);
90	    }
91	  }, [wantsToPlay, isVideoLoaded]);
92	
93	  const handleVideoCanPlay = useCallback(() => {
94	    setIsVideoLoaded(true);
95	  }, []);
96	
97	  // Handle tap on touch devices
98	  const handlePlayButtonClick = useCallback((e: React.MouseEvent) => {
99	    e.stopPropagation();
100	    e.preventDefault();
101	    setIsTouchPlaying((prev) => !prev);
102	  }, []);
103	
104	  return (
105	    <div className={cn('relative h-full w-full overflow-hidden', className)} {...hoverProps}>
106	      {/* Thumbnail (always rendered as base layer) */}
107	      <div
108	        className={cn(
109	          'absolute inset-0 transition-opacity duration-200',
110	          isVideoPlaying ? 'opacity-0' : 'opacity-100',
111	        )}
112	      >
113	        <VideoThumbnail videoUrl={videoUrl} hash={hash} isVisible={isVisible} />
114	      </div>
115	
116	      {/* Video element (loaded on hover) */}
117	      <video
118	        ref={videoRef}
119	        src={videoUrl}
120	        className={cn(
121	          'h-full w-full object-cover transition-opacity duration-200',
122	          isVideoPlaying ? 'opacity-100' : 'opacity-0',
123	        )}
124	        muted
125	        loop
126	        playsInline
127	        preload="none"
128	        onCanPlay={handleVideoCanPlay}
129	        aria-hidden="true"
130	      />
131	
132	      {/* Play/Pause button overlay */}
133	      <div
134	        className={cn(
135	          'absolute inset-0 flex items-center justify-center',
136	          'transition-opacity duration-200',
137	          // On touch devices: always show when not playing, hide when playing
138	          // On hover devices: controlled by hover state
139	          isTouchDevice
140	            ? isVideoPlaying
141	              ? 'opacity-0 pointer-events-none'
142	              : 'opacity-100'
143	            : isVideoPlaying
144	              ? 'opacity-0 pointer-events-none'
145	              : 'opacity-100 pointer-events-none',
146	        )}
147	      >
148	        <button
149	          type="button"
150	          onClick={handlePlayButtonClick}
151	          className={cn(
152	            'rounded-full bg-black/50 p-3 backdrop-blur-sm',
153	            'transition-transform duration-200',
154	            'group-hover:scale-110',
155	            // Make clickable on touch devices
156	            isTouchDevice ? 'pointer-events-auto cursor-pointer hover:bg-black/60' : '',
157	          )}
158	          aria-label={isVideoPlaying ? 'Pause video preview' : 'Play video preview'}
159	        >
160	          <Play className="h-6 w-6 text-white ml-0.5" fill="currentColor" />
161	        </button>
162	      </div>
163	
164	      {/* Playing indicator with pause button on touch devices */}
165	      {isVideoPlaying && (
166	        <div className="absolute bottom-2 left-2 flex items-center gap-1">
167	          {isTouchDevice ? (
168	            <button
169	              type="button"
170	              onClick={handlePlayButtonClick}
171	              className="flex items-center gap-1 px-2 py-1 bg-black/60 rounded text-white text-xs hover:bg-black/70 transition-colors"
172	              aria-label="Pause video preview"
173	            >
174	              <Pause className="h-3 w-3" fill="currentColor" />
175	              <span>Tap to pause</span>
176	            </button>
177	          ) : (
178	            <div className="flex items-center gap-1 px-2 py-1 bg-black/60 rounded text-white text-xs">
179	              <span className="relative flex h-2 w-2">
180	                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75" />
181	                <span className="relative inline-flex rounded-full h-2 w-2 bg-red-500" />
182	              </span>
183	              <span>Playing</span>
184	            </div>
185	          )}
186	        </div>
187	      )}
188	    </div>
189	  );
190	}
