      audio.volume = Math.max(0, startVolume * (1 - currentStep / fadeSteps));

      if (currentStep >= fadeSteps) {
        if (fadeIntervalRef.current !== undefined) {
          clearInterval(fadeIntervalRef.current);
          fadeIntervalRef.current = undefined;
