import { TooltipProvider } from '@app/components/ui/tooltip';
import { mockIntersectionObserver, mockMatchMedia } from '@app/tests/browserMocks';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter } from 'react-router-dom';
import { beforeEach, describe, expect, it, vi } from 'vitest';

import { AudioPreviewButton } from './components/AudioPreviewButton';
import { MediaCard } from './components/MediaCard';
import { MediaModal } from './components/MediaModal';

import type { MediaItem } from './types';

vi.mock('@app/utils/api', () => ({ getApiBaseUrl: () => 'http://localhost:3000' }));
vi.mock('@app/utils/media', () => ({
  downloadMediaItem: vi.fn(),
  formatBytes: (b: number) => `${b} B`,
  formatCost: (c: number) => `$${c.toFixed(2)}`,
  formatLatency: (ms: number) => `${ms}ms`,
  formatMediaDate: (d: string) => d,
  getKindIcon: () => (p: { className?: string }) => <svg data-testid="kind-icon" {...p} />,
  getKindLabel: (k: string) => k.charAt(0).toUpperCase() + k.slice(1),
  MEDIA_MAX_ZOOM: 5,
  MEDIA_MIN_ZOOM: 1,
  MEDIA_ZOOM_STEP: 1.5,
  MEDIA_ZOOM_WHEEL_STEP: 1.1,
}));
vi.mock('./components/AudioWaveform', () => ({ AudioWaveform: () => <div /> }));

const Wrapper = ({ children }: { children: ReactNode }) => (
  <TooltipProvider>
    <MemoryRouter>{children}</MemoryRouter>
  </TooltipProvider>
);

const item = (o: Partial<MediaItem> = {}): MediaItem => ({
  hash: 'abc123',
  mimeType: 'image/png',
  sizeBytes: 1024,
  kind: 'image',
  createdAt: '2024-01-01T00:00:00Z',
  url: '/blobs/abc123',
  context: { evalId: 'e', evalDescription: 'Test Evaluation', ...o.context },
  ...o,
});

describe('spec verification', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockMatchMedia({ matches: (q) => q === '(hover: hover)' });
    mockIntersectionObserver();
  });

  it('AudioPreviewButton play button hover/touch classes', () => {
    render(<AudioPreviewButton audioUrl="u" hash="h" />, { wrapper: Wrapper });
    const btn = screen.getByRole('button', { name: 'Play audio preview' });
    expect(btn).toHaveClass('pointer-events-none', 'opacity-0');
    expect(btn).toHaveClass('group-hover:pointer-events-auto', 'group-hover:opacity-100');
    expect(btn).toHaveClass(
      '[@media(hover:none)]:pointer-events-auto',
      '[@media(hover:none)]:opacity-100',
    );
  });

  it('MediaCard image surface click invokes onClick', async () => {
    const user = userEvent.setup();
    const onClick = vi.fn();
    render(<MediaCard item={item()} onClick={onClick} />, { wrapper: Wrapper });
    await user.click(screen.getByRole('img'));
    expect(onClick).toHaveBeenCalledTimes(1);
  });

  it('MediaCard video play button does NOT invoke onClick', async () => {
    const user = userEvent.setup();
    const onClick = vi.fn();
    render(<MediaCard item={item({ kind: 'video', mimeType: 'video/mp4' })} onClick={onClick} />, {
      wrapper: Wrapper,
    });
    await user.click(screen.getByRole('button', { name: 'Play video preview' }));
    expect(onClick).not.toHaveBeenCalled();
  });

  it('MediaCard download button touch classes', () => {
    render(<MediaCard item={item()} onClick={vi.fn()} />, { wrapper: Wrapper });
    expect(screen.getByLabelText('Download')).toHaveClass(
      '[@media(hover:none)]:h-11',
      '[@media(hover:none)]:w-11',
    );
  });

  it('MediaModal desktop/mobile actions + close + panel', () => {
    render(<MediaModal item={item()} items={[item()]} onClose={vi.fn()} onNavigate={vi.fn()} />, {
      wrapper: Wrapper,
    });
    const dialog = screen.getByRole('dialog');
    expect(dialog.lastElementChild).toHaveClass('min-w-0', 'w-full');

    const panel = screen.getByTestId('media-modal-details-panel');
    expect(panel).toHaveClass('min-h-0', 'overflow-hidden');

    const desktop = screen.getByTestId('media-modal-desktop-actions');
    expect(desktop).toHaveClass('hidden', 'md:flex', 'shrink-0');
    expect(within(desktop).getByRole('button', { name: 'Download' })).toHaveClass(
      '[@media(hover:none)]:h-11',
    );
    expect(within(desktop).getByRole('button', { name: 'Copy permalink' })).toHaveClass(
      '[@media(hover:none)]:h-11',
      '[@media(hover:none)]:w-11',
    );

    const mobile = screen.getByTestId('media-modal-mobile-actions');
    expect(within(mobile).getByRole('button', { name: 'Download' })).toHaveClass('h-11');
    expect(within(mobile).getByRole('button', { name: 'Copy permalink' })).toHaveClass(
      'h-11',
      'w-11',
    );

    expect(screen.getByRole('button', { name: 'Close' })).toHaveClass('h-11', 'w-11');
  });
});
